            earliest = schedule[(job_id, op_idx - 1)]['end'] if op_idx > 0 else 0
            baseline_machine = baseline_op['machine']
            baseline_dur = baseline_op['dur']
            baseline_start = baseline_op['start']
            alts = alternatives.get(key, [(baseline_machine, baseline_dur)])

            # Try to use baseline
            best_start = None
            best_machine = None
            best_dur = None

            baseline_end = baseline_start + baseline_dur
            if earliest <= baseline_start and not has_downtime_conflict(baseline_start, baseline_end, baseline_machine, downtime_windows):
                # Check machine conflict
                conflict = False
                for op in schedule.values():
                    if op['machine'] == baseline_machine:
                        if baseline_start < op['end'] and baseline_end > op['start']:
                            conflict = True
                            break
                if not conflict:
                    best_start, best_machine, best_dur = baseline_start, baseline_machine, baseline_dur

            # Try alternatives if baseline doesn't work
            if best_start is None:
                for machine, dur in alts:
                    test_start = find_free_slot(earliest, dur, machine, schedule, downtime_windows)
                    if best_start is None or test_start < best_start:
                        best_start, best_machine, best_dur = test_start, machine, dur

            if best_start is not None:
                schedule[key] = {
                    'job': job_id,
                    'op': op_idx,
                    'machine': best_machine,
                    'start': best_start,
                    'end': best_start + best_dur,
                    'dur': best_dur
                }

        if not unscheduled:
            break

    return schedule

def validate(schedule: dict, downtime_windows: Dict) -> Tuple[bool, List[str]]:
    """Validate schedule."""
    errors = []

    # Job precedence
    for (job_id, op_idx), op in schedule.items():
        if op_idx > 0:
            prev = schedule.get((job_id, op_idx - 1))
            if not prev or op['start'] < prev['end']:
                errors.append(f"Job {job_id} Op {op_idx}: precedence")

    # Downtime
    for (job_id, op_idx), op in schedule.items():
        if has_downtime_conflict(op['start'], op['end'], op['machine'], downtime_windows):
            errors.append(f"Job {job_id} Op {op_idx}: downtime")

    # Machine exclusivity
    by_machine = {}
    for op in schedule.values():
        m = op['machine']
        if m not in by_machine:
            by_machine[m] = []
        by_machine[m].append(op)

    for m, ops in by_machine.items():
        for i, op1 in enumerate(sorted(ops, key=lambda x: x['start'])):
            for op2 in sorted(ops, key=lambda x: x['start'])[i+1:]:
                if op1['end'] > op2['start']:
                    errors.append(f"Machine {m}: overlap")
                    break

    return len(errors) == 0, errors

def save_solution(schedule: dict, output_dir: str, status: str, makespan: int):
    os.makedirs(output_dir, exist_ok=True)
    schedule_list = sorted(schedule.values(), key=lambda x: (x['job'], x['op']))
    solution = {'status': status, 'makespan': makespan, 'schedule': schedule_list}

    with open(f'{output_dir}/solution.json', 'w') as f:
        json.dump(solution, f, indent=2)

    if schedule_list:
        pd.DataFrame(schedule_list)[['job', 'op', 'machine', 'start', 'end', 'dur']].to_csv(
            f'{output_dir}/schedule.csv', index=False)
    else:
        with open(f'{output_dir}/schedule.csv', 'w') as f:
            f.write("job,op,machine,start,end,dur\n")

def main():
    print("=" * 70)
    print("Job Shop Scheduling - Final Clean Version")
    print("=" * 70)

    alternatives = parse_instance('/app/data/instance.txt')
    downtime_windows = parse_downtime('/app/data/downtime.csv')

    with open('/app/data/baseline_solution.json') as f:
        baseline_data = json.load(f)

    baseline_makespan = baseline_data['makespan']
    print(f"\nBaseline makespan: {baseline_makespan}")
    print(f"Max allowed: {int(baseline_makespan * 1.1)}")

    print("\nScheduling...")
    schedule = schedule_jobs(baseline_data['schedule'], downtime_windows, alternatives)

    makespan = max(op['end'] for op in schedule.values()) if schedule else 0
    print(f"Generated makespan: {makespan}")

    print("\nValidating...")
    is_valid, errors = validate(schedule, downtime_windows)

    if is_valid:
        status = "FEASIBLE"
        print("✓ VALID")
    else:
        status = "INFEASIBLE"
        print("✗ INVALID:")
        for e in errors[:5]:
            print(f"  - {e}")

    save_solution(schedule, '/app/output', status, makespan)

    print("\n" + "=" * 70)
    print(f"Status: {status}")
    print(f"Makespan: {makespan} / {int(baseline_makespan * 1.1)}")
    print("=" * 70)

if __name__ == '__main__':
    main()

